#include <iostream>
#include <string>

int main() {
    std::string pattern;
    std::getline(std::cin, pattern);
    int countMatches = 0;
    for (int num = 0; num < 100000000; num += 25) {
        std::string numStr = std::to_string(num);
        if (numStr.length() != pattern.length()) continue;
        int xCharCode = -1;
        bool match = true;
        for (size_t index = 0; index < pattern.length(); ++index) {
            char pChar = pattern[index];
            char nChar = numStr[index];
            if (pChar == 'X') {
                if (xCharCode == -1) {
                    xCharCode = nChar;
                }
                if (nChar != xCharCode) {
                    match = false;
                    break;
                }
            } else if (pChar != '_') {
                if (nChar != pChar) {
                    match = false;
                    break;
                }
            }
        }
        if (match) countMatches++;
    }
    std::cout << countMatches << std::endl;
    return 0;
}
